function weightMap(list, exclude = new Set(['all', 'statewide'])) {
  const keys = list.map((x) => x.id).filter((id) => !exclude.has(id));
  const base = 1 / keys.length;
  const out = {};
  keys.forEach((id, i) => {
    // Mild authored skew so cubes aren't perfectly flat
    out[id] = Number((base * (0.75 + ((i * 17) % 7) * 0.08)).toFixed(4));
  });
  const sum = Object.values(out).reduce((a, b) => a + b, 0);
  Object.keys(out).forEach((k) => {
    out[k] = out[k] / sum;
  });
  return out;
}

